//! OKIR Intel Level Zero OpenCL C / SPIR-V Target Emitter.

use super::ir::{OkirFunction, OkirOpcode};
use std::fmt::Write;

#[must_use]
pub fn emit_spirv_opencl_kernel(func: &OkirFunction) -> String {
    let mut code = String::with_capacity(1024);
    code.push_str(
        "// Auto-generated by Oxide Kernel IR (OKIR) - Intel Level Zero SPIR-V / OpenCL C\n",
    );
    code.push_str("__kernel void ");
    code.push_str(&func.name);
    code.push_str("(\n");

    for (name, dt) in &func.input_buffers {
        let ty = match dt {
            super::ir::OkirDataType::F32 => "__global const float*",
            super::ir::OkirDataType::F16 => "__global const half*",
            _ => "__global const void*",
        };
        let _ = writeln!(code, "    {ty} {name},");
    }
    for (i, (name, dt)) in func.output_buffers.iter().enumerate() {
        let ty = match dt {
            super::ir::OkirDataType::F32 => "__global float*",
            super::ir::OkirDataType::F16 => "__global half*",
            _ => "__global void*",
        };
        let comma = if i + 1 == func.output_buffers.len() {
            ""
        } else {
            ","
        };
        let _ = writeln!(code, "    {ty} {name}{comma}");
    }
    code.push_str(") {\n");
    code.push_str("    int idx = get_global_id(0);\n");

    for inst in &func.instructions {
        match inst.opcode {
            OkirOpcode::Silu => {
                let op0 = inst.operands[0];
                let _ = writeln!(
                    code,
                    "    float r{} = r{op0} / (1.0f + native_exp(-r{op0}));",
                    inst.dest_reg
                );
            }
            OkirOpcode::Mul => {
                let _ = writeln!(
                    code,
                    "    float r{} = r{} * r{};",
                    inst.dest_reg, inst.operands[0], inst.operands[1]
                );
            }
            OkirOpcode::Add => {
                let _ = writeln!(
                    code,
                    "    float r{} = r{} + r{};",
                    inst.dest_reg, inst.operands[0], inst.operands[1]
                );
            }
            OkirOpcode::WarpReduceSum => {
                let _ = writeln!(
                    code,
                    "    float r{} = sub_group_reduce_add(r{});",
                    inst.dest_reg, inst.operands[0]
                );
            }
            _ => {}
        }
    }

    code.push_str("}\n");
    code
}
